'use client';

import React, { useState } from 'react';
import { X, Percent, DollarSign, Check, Tag, Lock } from 'lucide-react';
import '../styles/pos-rush.css';

interface POSDiscountModalProps {
    isOpen: boolean;
    onClose: () => void;
    onApplyDiscount: (type: 'percentage' | 'amount', value: number, couponCode?: string) => void;
}

const mockCoupons = [
    { code: 'SAVE10', description: '10% off orders above $50', type: 'percentage', value: 10, minOrder: 50 },
    { code: 'FREESHIP', description: 'Free delivery', type: 'amount', value: 5.99, minOrder: 40 },
    { code: 'COMBO20', description: '20% off combos', type: 'percentage', value: 20, minOrder: 0, disabled: true },
];

export const POSDiscountModal: React.FC<POSDiscountModalProps> = ({
    isOpen,
    onClose,
    onApplyDiscount
}) => {
    const [mode, setMode] = useState<'COUPON' | 'MANUAL'>('COUPON');
    const [discountType, setDiscountType] = useState<'percentage' | 'amount'>('percentage');
    const [discountValue, setDiscountValue] = useState<string>('');
    const [couponCode, setCouponCode] = useState('');
    const [managerPin, setManagerPin] = useState('');
    const [showPinInput, setShowPinInput] = useState(false);

    if (!isOpen) return null;

    const handleNumpadClick = (value: string) => {
        if (showPinInput) {
            if (value === 'C') setManagerPin('');
            else if (value !== '.') setManagerPin(prev => (prev + value).slice(0, 4));
            return;
        }

        if (value === 'C') {
            setDiscountValue('');
        } else if (value === '.') {
            if (!discountValue.includes('.')) {
                setDiscountValue(prev => prev + value);
            }
        } else {
            setDiscountValue(prev => prev + value);
        }
    };

    const handleApplyManual = () => {
        const val = parseFloat(discountValue);
        if (isNaN(val) || val <= 0) return;

        // Requirement: Manager Approval for >10% or Manual
        // "Manual discount: Manager PIN required" per spec
        if (!showPinInput) {
            setShowPinInput(true);
            return;
        }

        // Validate PIN (Mock check)
        if (managerPin === '1234') {
            onApplyDiscount(discountType, val);
            onClose();
        } else {
            alert('Invalid Manager PIN'); // In real app, toast
            setManagerPin('');
        }
    };

    const handleApplyCoupon = (coupon: any) => {
        if (coupon.disabled) return;
        onApplyDiscount(coupon.type as any, coupon.value, coupon.code);
        onClose();
    };

    return (
        <div className="pos-modal-overlay">
            <div className="pos-modal" style={{ width: '700px' }}>
                <div className="pos-modal-header">
                    <div className="pos-title-md" style={{ fontWeight: 700 }}>Apply Discount</div>
                    <button
                        className="pos-btn-secondary"
                        onClick={onClose}
                        style={{ width: '40px', height: '40px', padding: 0 }}
                    >
                        <X size={20} />
                    </button>
                </div>

                <div className="pos-modal-body" style={{ padding: 0 }}>
                    {/* Tabs */}
                    <div style={{ display: 'flex', borderBottom: '1px solid var(--pos-border-subtle)' }}>
                        <button
                            onClick={() => { setMode('COUPON'); setShowPinInput(false); }}
                            style={{
                                flex: 1,
                                padding: '16px',
                                background: mode === 'COUPON' ? 'var(--pos-action-primary)' : 'transparent',
                                color: mode === 'COUPON' ? 'white' : 'var(--pos-text-secondary)',
                                border: 'none',
                                fontWeight: 700,
                                cursor: 'pointer'
                            }}
                        >
                            AVAILABLE COUPONS
                        </button>
                        <button
                            onClick={() => { setMode('MANUAL'); setShowPinInput(false); }}
                            style={{
                                flex: 1,
                                padding: '16px',
                                background: mode === 'MANUAL' ? 'var(--pos-action-primary)' : 'transparent',
                                color: mode === 'MANUAL' ? 'white' : 'var(--pos-text-secondary)',
                                border: 'none',
                                fontWeight: 700,
                                cursor: 'pointer'
                            }}
                        >
                            MANUAL DISCOUNT
                        </button>
                    </div>

                    <div style={{ padding: '24px' }}>
                        {mode === 'COUPON' ? (
                            <div className="space-y-4">
                                {mockCoupons.map(coupon => (
                                    <div
                                        key={coupon.code}
                                        style={{
                                            display: 'flex',
                                            justifyContent: 'space-between',
                                            alignItems: 'center',
                                            padding: '16px',
                                            borderRadius: '12px',
                                            background: 'var(--pos-bg-card)',
                                            border: '1px solid var(--pos-border-subtle)',
                                            opacity: coupon.disabled ? 0.5 : 1
                                        }}
                                    >
                                        <div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                                                <Tag size={16} color="var(--pos-action-primary)" />
                                                <span style={{ fontWeight: 800, color: 'var(--pos-text-primary)' }}>{coupon.code}</span>
                                            </div>
                                            <div style={{ fontSize: '13px', color: 'var(--pos-text-secondary)' }}>{coupon.description}</div>
                                        </div>
                                        <div style={{ textAlign: 'right' }}>
                                            <div style={{ fontWeight: 800, color: 'var(--pos-action-primary)', marginBottom: '8px' }}>
                                                {coupon.type === 'amount' ? '-' : ''}${coupon.value}{coupon.type === 'percentage' ? '%' : ''}
                                            </div>
                                            {!coupon.disabled ? (
                                                <button
                                                    onClick={() => handleApplyCoupon(coupon)}
                                                    className="pos-btn-secondary"
                                                    style={{ padding: '4px 12px', minHeight: '32px', fontSize: '12px' }}
                                                >
                                                    APPLY
                                                </button>
                                            ) : (
                                                <span style={{ fontSize: '10px', color: 'var(--pos-state-error)' }}>NOT APPLICABLE</span>
                                            )}
                                        </div>
                                    </div>
                                ))}

                                <div style={{ marginTop: '24px' }}>
                                    <label style={{ fontSize: '12px', color: 'var(--pos-text-muted)', fontWeight: 700, textTransform: 'uppercase' }}>Enter Coupon Code</label>
                                    <div style={{ display: 'flex', gap: '12px', marginTop: '8px' }}>
                                        <input
                                            type="text"
                                            className="pos-input"
                                            placeholder="CODE"
                                            value={couponCode}
                                            onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                                        />
                                        <button className="pos-btn pos-btn-primary">APPLY</button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            // MANUAL MODE
                            <div>
                                {showPinInput ? (
                                    <div style={{ textAlign: 'center', maxWidth: '300px', margin: '0 auto' }}>
                                        <Lock size={48} className="mb-4 text-warning" style={{ margin: '0 auto 16px', color: '#F59E0B' }} />
                                        <h3 className="pos-title-md" style={{ marginBottom: '8px' }}>Manager Approval Required</h3>
                                        <p style={{ color: 'var(--pos-text-muted)', marginBottom: '24px' }}>Enter PIN to authorize manual discount.</p>

                                        <div style={{
                                            fontSize: '32px',
                                            fontWeight: 800,
                                            letterSpacing: '8px',
                                            marginBottom: '24px',
                                            height: '48px'
                                        }}>
                                            {managerPin.replace(/./g, '•')}
                                        </div>

                                        <div className="pos-grid-3">
                                            {[1, 2, 3, 4, 5, 6, 7, 8, 9, '', 0, 'C'].map((val, idx) => (
                                                val === '' ? <div key={idx} /> :
                                                    <button
                                                        key={val}
                                                        className="pos-btn-secondary"
                                                        style={{ height: '56px', fontSize: '20px' }}
                                                        onClick={() => handleNumpadClick(val.toString())}
                                                    >
                                                        {val}
                                                    </button>
                                            ))}
                                        </div>
                                        <div className="pos-grid-2" style={{ marginTop: '24px' }}>
                                            <button className="pos-btn-secondary" onClick={() => setShowPinInput(false)}>CANCEL</button>
                                            <button className="pos-btn-primary" onClick={handleApplyManual} disabled={managerPin.length < 4}>AUTHORIZE</button>
                                        </div>
                                    </div>
                                ) : (
                                    <>
                                        <div className="pos-grid-2" style={{ marginBottom: '24px' }}>
                                            <button
                                                className={`pos-btn ${discountType === 'percentage' ? 'pos-btn-primary' : 'pos-btn-secondary'}`}
                                                onClick={() => setDiscountType('percentage')}
                                            >
                                                <Percent size={20} style={{ marginRight: '8px' }} /> Percentage
                                            </button>
                                            <button
                                                className={`pos-btn ${discountType === 'amount' ? 'pos-btn-primary' : 'pos-btn-secondary'}`}
                                                onClick={() => setDiscountType('amount')}
                                            >
                                                <DollarSign size={20} style={{ marginRight: '8px' }} /> Amount
                                            </button>
                                        </div>

                                        <div style={{
                                            marginBottom: '24px',
                                            textAlign: 'center',
                                            padding: '16px',
                                            background: 'var(--pos-bg-card)',
                                            borderRadius: '12px',
                                            border: '1px solid var(--pos-border-subtle)'
                                        }}>
                                            <div style={{ fontSize: '14px', color: 'var(--pos-text-muted)', marginBottom: '8px', textTransform: 'uppercase' }}>
                                                Discount Value
                                            </div>
                                            <div style={{ fontSize: '48px', fontWeight: 800, color: 'var(--pos-text-primary)' }}>
                                                {discountType === 'amount' ? '$' : ''}{discountValue || '0'}{discountType === 'percentage' ? '%' : ''}
                                            </div>
                                        </div>

                                        <div className="pos-grid-3" style={{ maxWidth: '400px', margin: '0 auto', marginBottom: '24px' }}>
                                            {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'C'].map((val) => (
                                                <button
                                                    key={val}
                                                    className="pos-btn-secondary"
                                                    style={{ height: '64px', fontSize: '24px', fontWeight: 700 }}
                                                    onClick={() => handleNumpadClick(val.toString())}
                                                >
                                                    {val}
                                                </button>
                                            ))}
                                        </div>

                                        <button
                                            className="pos-btn-primary"
                                            style={{ width: '100%' }}
                                            onClick={handleApplyManual}
                                            disabled={!discountValue || parseFloat(discountValue) <= 0}
                                        >
                                            <Check size={20} style={{ marginRight: '8px' }} />
                                            Next: Authorize
                                        </button>
                                    </>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default POSDiscountModal;
